# Rebuild new supplementary benchmarks and revised main Figure 3 from bundled CSVs.
args<-commandArgs(TRUE);o<-if(length(args))args[1]else'.';td<-file.path(o,'supplementary_tables')
source(file.path(o,'cell_type_labels.R'))
read<-function(s)read.csv(file.path(td,s));s<-read('S12_ground_truth_accuracy.csv');f<-read('S13_RNA_fraction_pairs.csv');a<-read('S3_continuous_summary.csv');t<-read('S8_eqtl_tests.csv');cts<-c('Astro','Excit','Inhib','Oligo','OPC','Immune','Vascular');cols<-c(GAM6='#0072B2',contribution='#D55E00',expected_count='#009E73')
fig<-function(name,w,h,fun){for(ext in c('pdf','png')){file<-file.path(o,'figures',paste0(name,'.',ext));if(ext=='pdf')pdf(file,width=w,height=h,useDingbats=FALSE)else png(file,width=w,height=h,units='in',res=300,type='cairo');par(mar=c(4.4,4.6,3,1),mgp=c(2.7,.8,0),las=1);fun();dev.off()}}
lab<-function(x)mtext(x,3,line=1.1,adj=if(par("mfrow")[2]==1)-.028 else -.12,font=2,cex=1.2)
fig('Figure_S3_ground_truth_direct',10,6.4,function(){par(mfrow=c(2,4),mar=c(4.4,4.6,4,1),cex.main=.9);for(i in seq_along(cts)){ct<-cts[i];d<-subset(f,scenario=='direct'&cell_type==ct);z<-subset(s,scenario=='direct'&cell_type==ct);lim<-c(0,max(d$truth,d$estimate)*1.05);plot(d$truth,d$estimate,xlim=lim,ylim=lim,pch=16,col=adjustcolor('#0072B2',.7),xlab='True RNA fraction',ylab='Estimated RNA fraction',main=ct_name(ct,TRUE));abline(0,1,lty=2,col='gray40');lab(LETTERS[i]);legend('topleft',sprintf('r = %.3f\nMAE = %.2f pp',z$fraction_r,z$fraction_MAE*100),bty='n',cex=.70)};plot.new();text(.05,.75,'Direct aggregation\n40 evaluation donors\n7 cell types\n\nDashed line: equality\npp: percentage points',adj=c(0,1),cex=.9)})
# The standalone script preserves S4A-B and adds optional GAM6 to S4C.
script_arg<-grep('^--file=',commandArgs(FALSE),value=TRUE)
script_dir<-dirname(normalizePath(sub('^--file=','',script_arg[1])))
status<-system2(file.path(R.home('bin'),'Rscript'),c('--vanilla',shQuote(file.path(script_dir,'figure_expression_benchmark.R')),shQuote(o)))
if(status!=0L)stop('Figure S4 generation failed')
fig('Figure_S7_continuous_agreement_coverage',9,6.7,function(){par(mfrow=c(2,2),mar=c(4.4,4.6,4,1));i<-0;for(ct in c('Excit','Oligo'))for(metric in c('reference_agreement_among_calls','reference_recall_full_type')){i<-i+1;plot(NA,xlim=c(10,100),ylim=c(0,100),xlab='Profiles retained (%)',ylab=if(metric=='reference_agreement_among_calls')'Agreement among calls (%)'else'Full-type reference recall (%)',main=paste0(ct_name(ct),'\nSignal fraction 0.50'));lab(LETTERS[i]);for(m in names(cols)){d<-subset(a,source_type==ct&evaluated_type==ct&signal_fraction==.5&method==m);d<-d[order(d$retention),];lines(d$retention*100,d[[metric]]*100,col=cols[m],lwd=2)};if(i==1)legend('bottomleft',c('CDSeq2 (with gene-type\nprioritization)','Contribution','Expected count'),col=cols,lty=1,lwd=2,bty='n',cex=.75)}})
# Rebuild common-scale supplementary curves without obsolete specification.
cur<-read('S2_recovery_curves.csv');cur<-subset(cur,method!='GAM7')
fig('Figure_S1_all_type_recovery',11,6,function(){par(mfrow=c(2,4),mar=c(4.4,4.6,4,1),cex.main=.9);for(i in seq_along(cts)){ct<-cts[i];plot(NA,xlim=c(0,100),ylim=c(0,1),xlab='Profiles retained (%)',ylab='Median recovery r',main=ct_name(ct,TRUE));lab(LETTERS[i]);for(m in names(cols)){d<-subset(cur,stage=='validation'&cell_type==ct&method==m&retention>0);d<-d[order(d$retention),];lines(d$retention*100,d$median_Pearson,col=cols[m],lwd=2)}};plot.new();legend('center',c('CDSeq2 (with gene-type\nprioritization)','Contribution','Expected count'),col=cols,lty=1,lwd=2,bty='n',cex=.75)})
# All nominated Excit tests, same synthetic-variant order, all repeats.
variants<-sort(unique(t$variant));mx<-ceiling(max(-log10(pmax(t$q[t$cell_type=='Excit'&t$signal_ratio>0&t$engine %in% c('observed','CDSeq2','BayesPrism')],1e-300)),na.rm=TRUE))
for(strength in c(.8,.5)){nm<-if(strength==.8)'Figure_S5_eqtl_manhattan_strong'else'Figure_S6_eqtl_manhattan_moderate';fig(nm,11,8.6,function(){par(mfrow=c(3,3),mar=c(3.8,4.1,2.6,.8),cex=.80);idx<-0;for(rep in 1:3)for(eng in c('observed','CDSeq2','BayesPrism')){idx<-idx+1;d<-subset(t,cell_type=='Excit'&signal_ratio==strength&replicate==rep&engine==eng);d<-d[match(variants,d$variant),];stopifnot(nrow(d)==254,!anyNA(d$variant));y<--log10(pmax(d$q,1e-300));plot(seq_along(variants),y,pch=16,cex=.6,col=ifelse(d$injected,'#0072B2','#BBBBBB'),ylim=c(0,mx),xlab='Synthetic variant index',ylab=expression(-log[10](q[BH])),main=paste(if(eng=='observed')'Observed components'else if(eng=='CDSeq2')'CDSeq2 (without gene-type\nprioritization)'else eng,'| rep',rep),cex.main=.95);lab(LETTERS[idx]);abline(h=-log10(.05),lty=2,col='#555555');missing<-which(!is.finite(d$q));points(missing,rep(0,length(missing)),pch=4,col='#8B5C98',cex=.8);called<-which(d$called);points(called,y[called],pch=1,cex=.9,col=ifelse(d$correct_detection[called],'#0072B2','#CC3311'));if(idx==1)legend('topright',c('Injected excitatory-neuron effect','No excitatory-neuron injection','False / wrong sign'),col=c('#0072B2','#BBBBBB','#CC3311'),pch=c(16,16,1),cex=.52,bty='n')}})}
# Descriptive same-sign call overlap with observed components, no selection.
rows<-list();for(sc in unique(t$scenario))for(ct in cts)for(en in c('CDSeq2','BayesPrism')){d<-subset(t,scenario==sc&cell_type==ct&engine==en);r<-subset(t,scenario==sc&cell_type==ct&engine=='observed');r<-r[match(d$variant,r$variant),];stopifnot(identical(d$gene,r$gene));n<-sum(d$called&r$called&sign(d$effect)==sign(r$effect),na.rm=TRUE);rows[[length(rows)+1]]<-data.frame(scenario=sc,cell_type=ct,engine=en,signal_ratio=d$signal_ratio[1],replicate=d$replicate[1],inferred_calls=sum(d$called),observed_calls=sum(r$called),same_sign_overlap=n,agreement=if(sum(d$called))n/sum(d$called)else NA,recall=if(sum(r$called))n/sum(r$called)else NA)}
write.csv(do.call(rbind,rows),file.path(td,'S15_eqtl_observed_agreement.csv'),row.names=FALSE)


# All-type continuous results (supplementary Figure S2).
n<-read('S4_null_results.csv')
fig('Figure_S2_continuous_all_types',12,5.8,function(){par(mfrow=c(1,3),mar=c(5,8.1,3,1));for(metric in c('reference_agreement_among_calls','reference_recall_full_type')){mat<-sapply(c(.25,.5,.75),function(h)sapply(cts,function(ct){d<-subset(a,source_type==ct&evaluated_type==ct&method=='GAM6'&retention==.2&signal_fraction==h);d[[metric]]*100}));image(1:3,1:7,t(mat[7:1,]),zlim=c(0,100),col=hcl.colors(30,'Blues',rev=TRUE),axes=FALSE,xlab='Signal fraction',ylab='',main=if(metric=='reference_recall_full_type')'Full-type recall (%)'else'Agreement (%)');axis(1,1:3,c('.25','.50','.75'));axis(2,1:7,ct_name(rev(cts),TRUE),las=1,cex.axis=.72);for(i in 1:7)for(j in 1:3)text(j,8-i,if(is.na(mat[i,j]))'NA'else sprintf('%.1f',mat[i,j]),cex=.75,col=if(is.finite(mat[i,j])&&mat[i,j]>60)'white'else'black')};d<-subset(n,cell_type=='ALL');bx<-barplot(d$probability_any_false_call*100,names.arg=rep('',2),col=c('#0072B2','#999999'),ylim=c(0,8),ylab='Null traits with any rejection (%)',main='200 global-null traits');axis(1,at=bx,labels=c('CDSeq2\n(without gene-type\nprioritization)','Observed'),tick=FALSE,line=1.3,cex.axis=.78);abline(h=5,lty=2)})
